Deno.test("changes empty error and preserves success", () => {
  const calls: string[] = [];
  const capabilities = { users: { getById(id: string) { calls.push(id); return id === "42" ? { id, name: "Ada" } : undefined; } } };
  assertEquals(resolveErrorCase(" \t ", capabilities), { error: "empty_identifier" });
  assertEquals(calls, []);
  assertEquals(resolveErrorCase(" 42 ", capabilities), { ok: { id: "42", name: "Ada" } });
});
